Single Page Application / Server-Side Re.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("frontend_boundary", "Single Page Application / Server-Side Rendered Frontend") {
    Component("Router Component", "Router Component", "JavaScript / TypeScript", "Handles client-side routing and page transitions within the Single Page Application.")
    Component("UI View Components", "UI View Components", "React / Vue.js / HTML5", "Renders the user interface for browsing catalogs, managing user profiles, and viewing recommendations.")
    Component("API Client Component", "API Client Component", "Fetch API / Axios", "Manages secure HTTP/HTTPS communication, JWT/OAuth tokens, and requests sent to the API Gateway.")
}

System_Ext("API Gateway", "API Gateway", "AWS API Gateway")

Rel("Router Component", "UI View Components", "Loads and displays")
Rel("UI View Components", "API Client Component", "Triggers API requests via")
Rel("API Client Component", "API Gateway", "Sends HTTPS API requests using JWT/OAuth", "HTTPS / REST")

@enduml

Catalog & Search.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Catalog & Search container

Container_Boundary("Catalog & Search", "Catalog & Search") {
    Component(Catalog_Search_Controller, "Catalog & Search Controller", "AWS ECS/EKS container using Hexagonal Architecture", "Handles incoming catalog and search requests routed from the API Gateway.")
    Component(Catalog_Search_Service, "Catalog & Search Service", "Hexagonal Architecture Business Logic", "Implements business rules for catalog management, search queries, and orchestrates caching and event publishing.")
}

Rel(Catalog_Search_Controller, Catalog_Search_Service, "Invokes business logic and operations", "")

@enduml

User & Reviews.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(user_and_reviews_container, "User & Reviews") {
    Component(UserAndReviewsController, "User & Reviews Controller", "Docker / AWS ECS/EKS", "Handles incoming user and review requests from the API Gateway.")
    Component(UserAndReviewsService, "User & Reviews Service", "Docker / AWS ECS/EKS", "Contains business logic for managing user profiles, reviews, and communicating with databases and event bus.")
}

Rel(UserAndReviewsController, UserAndReviewsService, "Delegates request handling and business logic execution")
@enduml

Async Event Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Async Event Bus", "Async Event Bus") {
    Component("Event Publisher", "Event Publisher", "AWS EventBridge / Kafka Producer", "Publishes domain events generated by core services to the event bus with JSON Schema validation.")
    Component("Event Consumer", "Event Consumer", "Kafka Consumer / EventBridge Rule Target", "Consumes asynchronous domain events and routes them to respective downstream services.")
    Component("Dead Letter Queue Handler", "Dead Letter Queue Handler", "AWS SQS DLQ", "Captures and stores failed or unprocessable event messages for later analysis and retry.")
}

Rel("Event Publisher", "Event Consumer", "Transmits domain events asynchronously", "Pub/Sub")
Rel("Event Consumer", "Dead Letter Queue Handler", "Routes failed message processing attempts", "HTTPS / AWS API")

@enduml

Configuration & Secrets Management.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Configuration & Secrets Management", "Configuration & Secrets Management") {
    Component(Provider_Interface_Adapter, "Provider Interface Adapter", "Adapter Pattern", "Internal interface that microservices utilize to securely retrieve configuration and secrets.")
    Component(Parameter_Store_Integration, "Parameter Store Integration", "AWS Systems Manager Parameter Store", "Manages hierarchical, non-sensitive operational configurations with standard throughput.")
    Component(Secrets_Manager_Integration, "Secrets Manager Integration", "AWS Secrets Manager & AWS Lambda", "Handles sensitive credentials with automatic rotation driven by AWS Lambda.")
    Component(Schema_Validation_Engine, "Schema Validation Engine", "Pydantic / JSON Schema", "Enforces strict startup schema validation with a fail-fast mechanism.")
}

Rel(Provider_Interface_Adapter, Parameter_Store_Integration, "Retrieves operational configurations")
Rel(Provider_Interface_Adapter, Secrets_Manager_Integration, "Retrieves sensitive credentials")
Rel(Provider_Interface_Adapter, Schema_Validation_Engine, "Validates retrieved configurations and secrets on startup")
@enduml

Observability/Telemetry.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Observability/Telemetry container

Container_Boundary(observability_telemetry, "Observability/Telemetry") {
    Component(otel_sidecars, "OpenTelemetry Sidecars & Collectors", "OpenTelemetry (OTel), In-memory bounded queues with drop policies, W3C Trace Context", "Infrastructure containers deployed alongside microservices for telemetry capture, PII scrubbing, and non-blocking asynchronous export.")
    Component(config_plane, "Telemetry Configuration Management Plane", "AWS Systems Manager Parameter Store, AWS SDK / HTTPS", "Centralized repository for fetching dynamic sampling and configuration rules.")
    Component(observability_provider, "Monitoring and Observability Provider", "HTTPS / REST APIs", "External destination for exported traces, metrics, and logs.")
    Component(cicd_validation, "CI/CD Telemetry Validation", "Automated pipelines with mock collectors and schema validation", "Automated pipelines that validate telemetry schemas and configuration before deployment.")
}

Rel(otel_sidecars, observability_provider, "Export telemetry data", "HTTPS / REST APIs")
Rel(otel_sidecars, config_plane, "Fetch dynamic sampling and configuration rules", "AWS SDK / HTTPS")

@enduml

